* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    width: 100%;
    height: 100%;
    font-family: 'Arial', sans-serif;
    background: #1a1a1a;
    color: #fff;
    overflow: hidden;
}

#game-container {
    width: 100%;
    height: 100%;
    position: relative;
}

canvas {
    display: block;
    width: 100%;
    height: 100%;
}

#ui-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    font-family: 'Courier New', monospace;
}

#hud {
    position: absolute;
    top: 20px;
    left: 20px;
    background: rgba(0, 0, 0, 0.7);
    padding: 15px;
    border: 1px solid #00ff00;
    border-radius: 4px;
    min-width: 200px;
}

#status {
    color: #00ff00;
    font-size: 14px;
    line-height: 1.5;
}

/* Loading screen */
.loading {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    z-index: 1000;
}

.loading h1 {
    font-size: 32px;
    margin-bottom: 20px;
    color: #00ff00;
}

.loading-spinner {
    width: 50px;
    height: 50px;
    border: 3px solid #00ff00;
    border-top: 3px solid transparent;
    border-radius: 50%;
    animation: spin 1s linear infinite;
    margin: 0 auto;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Responsive */
@media (max-width: 768px) {
    #hud {
        top: 10px;
        left: 10px;
        padding: 10px;
        font-size: 12px;
    }

    #status {
        font-size: 12px;
    }
}

